// scripts/batch/templates/workable.js
// Generator for a Workable ATS source extractor. Returns the full text of
// src/scrapers/extractors/jobs/<name>.js. The generated file uses plain
// fetch() -- no Puppeteer page needed. The page argument is passed by the
// orchestrator (withPage) but intentionally unused; the orchestrator was
// not modified, so a browser context is created and immediately idle per
// scrape. Wasteful but contractually clean, and simple to remove later.
//
// Workable API contract:
//   GET https://apply.workable.com/api/v1/widget/accounts/{slug}?details=true
//   200 -> { name, description, jobs: [ {title, shortcode, url, ...} ] }
//   jobs === [] means "no open roles right now" -- a valid state, not drift.
//   The extractor sets meta.atsEmpty = true on that path so verify treats
//   it as pass. Additions/removals/modifications between runs are normal.

const { sanitizeJobFields } = require('../../../src/scrapers/jobs');

// Escape a string for safe embedding in a single-quoted JS literal.
function q(s) {
    return String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
}

function renderWorkable(name, slug) {
    if (!/^[a-z0-9_-]+$/.test(name)) throw new Error(`invalid source name: ${name}`);
    if (!slug) throw new Error('renderWorkable: slug is required');
    return `// Extractor: ${name} (jobs) -- Workable ATS API.
// Generated by scripts/batch/templates/workable.js. Hand-verify before commit;
// re-run \`pulchowk-events verify ${name}\` after any edit.
//
// Uses plain fetch() -- no browser. The page argument is passed by the
// orchestrator but intentionally unused.
//
// API: GET https://apply.workable.com/api/v1/widget/accounts/{slug}?details=true
// Empty jobs array is a valid state (no open roles right now) --
// meta.atsEmpty is set true so verify passes rather than reporting drift.

const { safeDiscovered, safeUnitDone } = require('../../progress');
const { sanitizeJobFields } = require('../../jobs');

const WORKABLE_SLUG = '${q(slug)}';
const WORKABLE_API = \`https://apply.workable.com/api/v1/widget/accounts/\${WORKABLE_SLUG}?details=true\`;

module.exports = {
    // browserless: true tells _orchestrate / verify-source / verify-worker
    // to skip Puppeteer entirely. This extractor uses fetch() only, so
    // launching Chromium is wasted work -- and worse, closeBrowser()
    // can hang 40s+ on an empty page, pinning the worker.
    browserless: true,
    async extract(page, { progress, meta }) {
        meta.pagesVisited++;
        const res = await fetch(WORKABLE_API, {
            headers: { 'User-Agent': 'Mozilla/5.0', 'Accept': 'application/json' },
            // ATS APIs rate-limit aggressively. Without a timeout, a
            // rate-limited call hangs forever and burns the full per-site
            // timeout in verify. 15s is generous for a JSON response.
            signal: AbortSignal.timeout(15000)
        });
        if (!res.ok) {
            throw new Error('workable API HTTP ' + res.status);
        }
        const data = await res.json();
        const company = data.name || '${q(name)}';
        const jobs = Array.isArray(data.jobs) ? data.jobs : [];

        meta.listingHits = jobs.length;
        safeDiscovered(progress, jobs.length);

        if (jobs.length === 0) {
            meta.atsEmpty = true;
            return { items: [], meta };
        }

        const items = [];
        for (const j of jobs) {
            try {
                const loc = Array.isArray(j.locations) && j.locations[0] ? j.locations[0] : null;
                const location = loc
                    ? [loc.city, loc.region, loc.country].filter(Boolean).join(', ')
                    : ([j.city, j.state, j.country].filter(Boolean).join(', ') || null);

                const item = {
                    id: \`workable-${q(slug)}-\${j.shortcode || j.title}\`,
                    title: j.title || 'Untitled Job',
                    company,
                    companyUrl: null,
                    companyLogoUrl: null,
                    location,
                    employmentType: j.employment_type || null,
                    attendanceMode: j.telecommuting ? 'remote' : 'in-person',
                    salary: null,
                    experience: j.experience || null,
                    level: j.education || null,
                    openings: null,
                    description: '',
                    responsibilities: '',
                    requirements: '',
                    skills: [],
                    companyDescription: data.description || '',
                    companyLocation: null,
                    companyAddress: null,
                    applicationEndsRaw: null,
                    applicationEndsDate: null,
                    daysLeftAtListTime: null,
                    url: j.url || j.shortlink || null,
                    registrationUrl: j.application_url || j.url || null,
                    source: '${q(name)}',
                    scrapedAt: Date.now(),
                    publishedAt: j.published_on || null
                };

                sanitizeJobFields(item);
                if (item.title && item.url) {
                    items.push(item);
                } else {
                    meta.detailParseFailures++;
                }
            } catch (e) {
                meta.detailParseFailures++;
                console.warn('  [${q(name)}] workable job parse failed: ' + e.message);
            } finally {
                safeUnitDone(progress);
            }
        }

        return { items, meta };
    }
};
`;
}

module.exports = { renderWorkable };
